import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlTextComponent } from '@domg-wc/components/atom';
import { VlDatepickerComponent, VlFormLabelComponent, VlFormMessageComponent } from '@domg-wc/components/form';

registerWebComponents([
    VlDatepickerComponent,
    VlFormLabelComponent,
    VlFormMessageComponent,
    VlButtonComponent,
    VlTextComponent,
]);

// vl-change volgt op elke wijziging van de waarde, ook door code; vl-input enkel op invoer van de gebruiker.
// event.detail.value is de waarde in ISO-formaat, bv. '2023-12-31' (type date).
document.querySelector('#datepicker-default').addEventListener('vl-change', (event) => {
    console.log(event.detail.value);
});
